#include "web.cpp"
int main(){string id;while(cin>>id){double p[35];for(double&v:p)cin>>v;Hero h;Scenario sc;Build b;int aug;Options o;auto err=configure(p,35,h,sc,b,aug,o);if(!err.empty()){cerr<<err;return 1;}int pass=-1,fail=-1,score=-1,finefail=-1;cout<<"{\"id\":\""<<id<<"\",\"stages\":[";bool first=true;for(int d=300;d<=20000;d+=50){o.dps=d;Sim sim(h,sc,b,aug,o);sim.capture=false;auto r=sim.run();if(!first)cout<<',';first=false;cout<<'['<<d<<','<<r.alive<<','<<r.frame<<']';if(!r.alive){fail=d;break;}pass=d;}cout<<"],\"refinement\":[";first=true;score=pass;if(fail>=0)for(int d=max(300,pass+1);d<=fail;d++){o.dps=d;Sim sim(h,sc,b,aug,o);sim.capture=false;auto r=sim.run();if(!first)cout<<',';first=false;cout<<'['<<d<<','<<r.alive<<','<<r.frame<<']';if(!r.alive){finefail=d;break;}score=d;}cout<<"],\"passedDps\":"<<pass<<",\"failedDps\":"<<fail<<",\"score\":"<<score<<",\"refinedFail\":"<<finefail<<"}"<<endl;}}
